import json
import math
import os
import signal
import sys
import tempfile
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import unquote_to_bytes, urlsplit


MAX_BODY = 1024 * 1024


class Store:
    def __init__(self, filename: str):
        self.path = Path(filename)
        self.lock = threading.RLock()
        self.entries = {}
        self._load()

    @staticmethod
    def _live(entry, now):
        expiry = entry.get("expires_at")
        return expiry is None or expiry > now

    def _load(self):
        with self.lock:
            if not self.path.exists():
                return
            try:
                with self.path.open("r", encoding="utf-8") as handle:
                    payload = json.load(handle)
                if not isinstance(payload, dict):
                    raise ValueError("top-level JSON is not an object")
                now = time.time()
                changed = False
                for key, entry in payload.items():
                    if (isinstance(key, str) and isinstance(entry, dict)
                            and "value" in entry
                            and (entry.get("expires_at") is None
                                 or isinstance(entry.get("expires_at"), (int, float)))):
                        if self._live(entry, now):
                            self.entries[key] = entry
                        else:
                            changed = True
                    else:
                        changed = True
                if changed:
                    self._persist()
            except (OSError, ValueError, TypeError, json.JSONDecodeError) as exc:
                print(f"warning: unable to load data file: {exc}", file=sys.stderr, flush=True)

    def _purge(self):
        now = time.time()
        expired = [key for key, entry in self.entries.items() if not self._live(entry, now)]
        if expired:
            for key in expired:
                del self.entries[key]
            self._persist()

    def _persist(self):
        self.path.parent.mkdir(parents=True, exist_ok=True)
        descriptor, temporary = tempfile.mkstemp(prefix=".kv-", suffix=".tmp", dir=self.path.parent)
        try:
            with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
                json.dump(self.entries, handle, ensure_ascii=False, separators=(",", ":"), allow_nan=False)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, self.path)
        except Exception:
            try:
                os.unlink(temporary)
            except OSError:
                pass
            raise

    def get(self, key):
        with self.lock:
            self._purge()
            entry = self.entries.get(key)
            return None if entry is None else entry["value"]

    def put(self, key, value, ttl):
        with self.lock:
            self._purge()
            created = key not in self.entries
            self.entries[key] = {"value": value, "expires_at": None if ttl is None else time.time() + ttl}
            self._persist()
            return created

    def delete(self, key):
        with self.lock:
            self._purge()
            if key not in self.entries:
                return False
            del self.entries[key]
            self._persist()
            return True

    def keys(self):
        with self.lock:
            self._purge()
            return sorted(self.entries)


